```javascript
import {
  Group, Mesh, PlaneGeometry,
  MeshStandardNodeMaterial, MeshBasicNodeMaterial,
  DirectionalLight, AmbientLight
} from 'three/webgpu';
import {
  uniform, time, vec3, vec4, mix, smoothstep, uv, texture, positionWorld, normalWorld,
  mul, add, dot, max, abs, sin, cos, clamp, length, normalize, color as colorNode,
  float, timerLocal, vec2
} from 'three/tsl';
import { gsap } from 'gsap';

const CARD_COUNT = 5;
const CARD_WIDTH = 1.6;
const CARD_HEIGHT = 1.0;
const CARD_PITCH = 1.85;
const BEVEL = 0.025;
const STRIP_Y_ROT = -18 * Math.PI / 180;

const CAPTIONS = [
  'NA-01 MERIDIAN',
  'NA-02 NOCTURNE',
  'NA-03 SIGNAL',
  'NA-04 VANTAGE',
  'NA-05 ARCHIVE'
];

const TEXTURE_URL = '/prism-mock/home/nodes/parallax-stack.png';

export default function createNode(config, ctx) {
  const group = new Group();
  const cards = [];
  const cleanupFns = [];
  let stripGroup = new Group();
  let snapTimeline = null;
  let focusedIndex = 2; // center

  // --- Backdrop with gradient ---
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    side: ctx.THREE.DoubleSide,
    roughness: 0.8,
    metalness: 0.1
  });
  const gradientTop = colorNode('#12121a');
  const gradientBottom = colorNode('#0b0b10');
  const uvCoord = uv();
  // gradient from bottom (0) to top (1)
  const gradientMix = smoothstep(0.0, 1.0, uvCoord.y);
  const finalColor = mix(gradientBottom, gradientTop, gradientMix);
  backdropMat.colorNode = finalColor;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // --- Lighting ---
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);

  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-2, 1, -3);
  group.add(rimLight);

  const fillLight = new DirectionalLight(0x404060, 0.4);
  fillLight.position.set(0, -1, 2);
  group.add(fillLight);

  const ambientLight = new AmbientLight(0x404060, 0.6);
  group.add(ambientLight);

  // --- Headline ---
  const headlineText = config.textContent?.[0]?.text || 'The collection';
  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left'
  });
  headline.position.set(-2.6, 1.5, 0);
  group.add(headline);

  // --- Body ---
  const bodyText = config.textContent?.[1]?.text || 'Five calibres. One discipline.';
  const body = ctx.fontAtlas.createText(bodyText, {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'left'
  });
  body.position.set(-2.6, -1.5, 0);
  group.add(body);

  // --- Create cards ---
  // We'll load texture once, then assign distinct UV slices
  const loadPromise = ctx.textureLoader.loadTexture(TEXTURE_URL);
  let sharedTexture = null;

  loadPromise.then((tex) => {
    sharedTexture = tex;
    tex.wrapS = tex.wrapT = ctx.THREE.RepeatWrapping;
    tex.repeat.set(1 / CARD_COUNT, 1);
    // Update each card's material
    cards.forEach((card, i) => {
      card.plateMat.map = tex;
      card.plateMat.colorNode = null;
      // Distinct horizontal slice
      const offsetX = (i / CARD_COUNT); // 0, 0.2, 0.4, 0.6, 0.8
      tex.offset.x = offsetX;
      card.plateMat.needsUpdate = true;
    });
  }).catch(() => {
    // fallback: use spec surface color
    cards.forEach((card) => {
      card.plateMat.colorNode = colorNode('#14141a');
    });
  });

  for (let i = 0; i < CARD_COUNT; i++) {
    const isFocused = i === focusedIndex;
    const xOffset = (i - 2) * CARD_PITCH;

    // Card plate
    const plateGeo = new PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
    const plateMat = new MeshStandardNodeMaterial({
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      side: ctx.THREE.DoubleSide,
      // placeholder color (will be replaced by texture)
      color: '#14141a'
    });
    const plate = new Mesh(plateGeo, plateMat);
    plate.position.x = 0;

    // Bevel frame
    const bevelGeo = new PlaneGeometry(CARD_WIDTH + BEVEL * 2, CARD_HEIGHT + BEVEL * 2);
    const bevelMat = new MeshStandardNodeMaterial({
      color: '#16161d',
      roughness: 0.6,
      metalness: 0.3,
      side: ctx.THREE.DoubleSide
    });
    const bevel = new Mesh(bevelGeo, bevelMat);
    bevel.position.z = -0.01;

    const cardGroup = new Group();
    cardGroup.add(bevel);
    cardGroup.add(plate);
    cardGroup.position.x = xOffset;

    // Store scroll offset uniform per card (for UV shift)
    const scrollOffset = uniform(0);
    cards.push({
      group: cardGroup,
      plate,
      bevel,
      plateMat,
      bevelMat,
      isFocused,
      scrollOffset,
      originalX: xOffset
    });

    // Focused card setup
    if (isFocused) {
      cardGroup.rotation.y = -STRIP_Y_ROT;
      cardGroup.scale.set(1, 1, 1);

      // Underline bar with emissive
      const barGeo = new PlaneGeometry(CARD_WIDTH, 0.035);
      const barMat = new MeshBasicNodeMaterial({
        color: '#ff2a38'
      });
      barMat.emissiveNode = colorNode('#ff2a38');
      barMat.emissiveIntensityNode = float(1.3);
      const bar = new Mesh(barGeo, barMat);
      bar.position.y = -0.55;
      bar.position.z = 0.02;
      cardGroup.add(bar);

      // Caption for focused card (accent color)
      const caption = ctx.fontAtlas.createText(CAPTIONS[i], {
        fontSize: 18,
        color: '#ff2a38',
        align: 'center',
        letterSpacing: 0.08 * 18
      });
      caption.position.set(0, -0.65, 0.02);
      caption.scale.set(0.005, 0.005, 0.005);
      cardGroup.add(caption);
    } else {
      const distance = Math.abs(i - focusedIndex);
      const opacity = 1.0 - (distance * 0.22);
      plateMat.opacity = Math.max(0.55, opacity);
      plateMat.transparent = true;
      bevelMat.opacity = Math.max(0.55, opacity);
      bevelMat.transparent = true;
      cardGroup.scale.set(0.92, 0.92, 0.92);
      cardGroup.rotation.y = 0; // not facing camera

      // Caption for non-focused cards (paper color)
      const caption = ctx.fontAtlas.createText(CAPTIONS[i], {
        fontSize: 18,
        color: '#e8ecf2',
        align: 'center',
        letterSpacing: 0.08 * 18
      });
      caption.position.set(0, -0.65, 0.02);
      caption.scale.set(0.004, 0.004, 0.004);
      cardGroup.add(caption);
    }

    // Additional ambient light per card? Not needed.
    stripGroup.add(cardGroup);
  }

  stripGroup.rotation.y = STRIP_Y_ROT;
  group.add(stripGroup);

  // --- Parallax scroll primitive (single application) ---
  // We'll store the scroll offset to update UVs
  const scrollUniform = uniform(0);
  // This primitive will translate the strip group based on scroll
  const primResult = ctx.primitives['parallax-scroll'](stripGroup, {
    intensity: 0.5,
    onUpdate: (offset) => {
      scrollUniform.value = offset;
      // Update UV offsets per card: base slice + parallax shift
      if (sharedTexture) {
        cards.forEach((card, i) => {
          const baseOffsetX = i / CARD_COUNT;
          // shift UV +/-0.04 based on scroll
          const shift = offset * 0.04;
          sharedTexture.offset.x = baseOffsetX + shift;
        });
      }
    }
  });
  if (primResult) {
    if (primResult.timeline) cleanupFns.push(() => primResult.timeline.kill());
    if (primResult.cleanup) cleanupFns.push(primResult.cleanup);
  }

  // --- Snap-to-card on scroll end ---
  const snapToCard = (targetIndex) => {
    if (snapTimeline) snapTimeline.kill();
    const prevFocused = focusedIndex;
    focusedIndex = targetIndex;

    // Compute target x for strip to center focused card
    const targetX = (targetIndex - 2) * CARD_PITCH * Math.sin(STRIP_Y_ROT) * -1;

    snapTimeline = gsap.timeline();
    snapTimeline.to(stripGroup.position, {
      x: targetX,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      onComplete: () => {
        // Update focus state on all cards
        cards.forEach((card, i) => {
          const isFocusedNow = i === targetIndex;
          if (isFocusedNow) {
            // Scale and rotation to focus
            gsap.to(card.group.scale, {
              x: 1, y: 1, z: 1,
              duration: 0.6,
              ease: 'power4.out',
              overwrite: 'auto'
            });
            gsap.to(card.group.rotation, {
              y: -STRIP_Y_ROT,
              duration: 0.6,
              ease: 'power4.out',
              overwrite: 'auto'
            });
            // Opacity back to full
            gsap.to(card.plateMat, {
              opacity: 1,
              duration: 0.6,
              ease: 'power2.out',
              overwrite: 'auto'
            });
            gsap.to(card.bevelMat, {
              opacity: 1,
              duration: 0.6,
              ease: 'power2.out',
              overwrite: 'auto'
            });
          } else {
            const distance = Math.abs(i - targetIndex);
            const opacity = 1.0 - (distance * 0.22);
            gsap.to(card.group.scale, {
              x: 0.92, y: 0.92, z: 0.92,
              duration: 0.6,
              ease: 'power4.out',
              overwrite: 'auto'
            });
            gsap.to(card.group.rotation, {
              y: 0,
              duration: 0.6,
              ease: 'power4.out',
              overwrite: 'auto'
            });
            gsap.to(card.plateMat, {
              opacity: Math.max(0.55, opacity),
              duration: 0.6,
              ease: 'power2.out',
              overwrite: 'auto'
            });
            gsap.to(card.bevelMat, {
              opacity: Math.max(0.55, opacity),
              duration: 0.6,
              ease: 'power2.out',
              overwrite: 'auto'
            });
          }
        });
      }
    });
    cleanupFns.push(() => { if (snapTimeline) snapTimeline.kill(); });
  };

  // Initial snap to center
  snapToCard(2);

  // --- Event handlers (scroll) ---
  group.userData.handlers = {
    scroll: (event) => {
      const delta = event.deltaY || event.detail?.deltaY || 0;
      const scrollAmount = delta * 0.001;
      let newIndex = focusedIndex + Math.round(scrollAmount);
      newIndex = Math.max(0, Math.min(CARD_COUNT - 1, newIndex));
      if (newIndex !== focusedIndex) {
        snapToCard(newIndex);
      }
    }
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    cleanupFns.forEach(fn => fn());
    if (snapTimeline) snapTimeline.kill();
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
    // Dispose text objects
    [headline, body].forEach(text => {
      if (text && text.parent) {
        text.parent.remove(text);
        text.traverse((child) => {
          if (child.isMesh) {
            child.geometry?.dispose();
            child.material?.dispose();
          }
        });
      }
    });
  };

  return group;
}
